import type {
  PoMatchExplanationResponse,
  PoMatchPass,
  PoMatchStage,
} from 'src/services/analytics/PoMatchExplanationService';

export interface PoReplayStep {
  kind: 'pass' | 'stage' | 'outcome';
  stage: PoMatchStage | null;
  pass: PoMatchPass | null;
}
/** What the transformation rules did to the document before matching. */
export interface PoReplayTransformationRule {
  ruleKey: string;
  name: string;
  scope: string;
  outcome: string;
  table: string;
}
export interface PoReplayTransformation {
  /** False for documents saved before the engine started recording runs. */
  recorded: boolean;
  at: string;
  rules: PoReplayTransformationRule[];
  applied: PoReplayTransformationRule[];
  /** The rule that took the PO match during a save, if one did. */
  dropped: { rule: string; table: string } | null;
}

export interface PoReplay {
  transformation: PoReplayTransformation | null;
  reason: '' | 'invalid' | 'missing' | 'legacy' | 'unsupported' | 'incomplete';
  steps: PoReplayStep[];
  stages: PoMatchStage[];
  evaluatedAt: string;
  version: string;
  hash: string;
  basis: 'same' | 'different' | 'unknown';
  result: 'full' | 'partial' | 'none' | 'unknown';
  matched: number | null;
  openPo: number | null;
  openTable: number | null;
}

const record = (value: unknown): value is Record<string, unknown> =>
  Boolean(value) && typeof value === 'object' && !Array.isArray(value);
const string = (value: unknown): string =>
  typeof value === 'string' ? value.trim() : '';
export const replayCount = (value: unknown): number | null =>
  typeof value === 'number' && Number.isSafeInteger(value) && value >= 0
    ? value
    : null;
export const validReplayDocumentId = (value: string): boolean =>
  Boolean(value.trim()) &&
  value.trim().length <= 200 &&
  !/[\s/?#\\]/u.test(value.trim()) &&
  !Array.from(value).some(
    (character) =>
      character.charCodeAt(0) < 32 || character.charCodeAt(0) === 127,
  );
const label = (value: unknown): boolean =>
  record(value) && typeof value.en === 'string' && typeof value.de === 'string';
const hash = (value: unknown): string =>
  string(value)
    .replace(/^sha256:/i, '')
    .toLowerCase();

/** The transformation context the API attaches to a document view, or null. */
export function readTransformation(value: unknown): PoReplayTransformation | null {
  if (!record(value) || !record(value.transformation)) return null;
  const raw = value.transformation;
  const rule = (entry: unknown): PoReplayTransformationRule | null => {
    if (!record(entry)) return null;
    const ruleKey = string(entry.rule_key);
    if (!ruleKey) return null;
    return {
      ruleKey,
      name: string(entry.display_name) || ruleKey,
      scope: string(entry.scope),
      outcome: string(entry.outcome),
      table: string(entry.table_name),
    };
  };
  const rules = (Array.isArray(raw.rules) ? raw.rules : [])
    .map(rule)
    .filter((entry): entry is PoReplayTransformationRule => entry !== null);
  const drop = record(raw.last_drop) ? raw.last_drop : null;
  const dropped =
    drop && string(drop.stage) === 'transformation_rule'
      ? { rule: string(drop.rule_name) || string(drop.rule_key), table: string(drop.table_name) }
      : null;
  return {
    recorded: raw.recorded === true,
    at: string(raw.at),
    rules,
    applied: rules.filter((entry) => entry.outcome === 'applied'),
    dropped,
  };
}

/** Read recorded stage results, never simulate a match or trust the terminal's name.
 * The v1 API calls ANY matched group "match_successful", including partial matches.
 * Its outcome ID lists are capped: only recorded stage counters prove open line counts.
 */
export function buildPoReplay(value: unknown, docId: string): PoReplay {
  const result: PoReplay = {
    transformation: readTransformation(value),
    reason: 'invalid',
    steps: [],
    stages: [],
    evaluatedAt: '',
    version: '',
    hash: '',
    basis: 'unknown',
    result: 'unknown',
    matched: null,
    openPo: null,
    openTable: null,
  };
  if (
    !record(value) ||
    value.mode !== 'document' ||
    value.doc_id !== docId ||
    !validReplayDocumentId(docId)
  )
    return result;
  if (value.engine === 'legacy') return { ...result, reason: 'legacy' };
  if (value.trace_missing_reason || !record(value.trace))
    return { ...result, reason: 'missing' };
  if (value.engine !== 'rules' || value.trace.schema_version !== 1)
    return { ...result, reason: 'unsupported' };
  if (!Array.isArray(value.stages) || !value.stages.length)
    return { ...result, reason: 'incomplete' };
  const seen = new Set<string>();
  let previousNo = 0;
  for (const stage of value.stages) {
    if (
      !record(stage) ||
      !string(stage.key) ||
      seen.has(stage.key as string) ||
      replayCount(stage.no) === null ||
      Number(stage.no) <= previousNo ||
      !label(stage.label) ||
      !label(stage.condition) ||
      !Array.isArray(stage.passes) ||
      !stage.passes.length
    )
      return result;
    seen.add(stage.key as string);
    previousNo = Number(stage.no);
    if (
      !['pass', 'fail', 'skip'].includes(String(stage.state)) ||
      stage.skipped_reason === 'stage_not_recorded' ||
      (stage.state === 'skip' && !string(stage.skipped_reason))
    )
      return { ...result, reason: 'incomplete' };
    const passKeys = new Set<string>();
    for (const pass of stage.passes) {
      if (
        !record(pass) ||
        !string(pass.key) ||
        passKeys.has(pass.key as string) ||
        !label(pass.label) ||
        typeof pass.runs !== 'boolean' ||
        !Array.isArray(pass.failed_columns) ||
        pass.failed_columns.some((column: unknown) => !record(column)) ||
        (pass.attempts != null &&
          (!Array.isArray(pass.attempts) ||
            pass.attempts.some((attempt: unknown) => !record(attempt))))
      )
        return result;
      passKeys.add(pass.key as string);
      if (
        !['pass', 'fail', 'skip'].includes(String(pass.state)) ||
        pass.skipped_reason === 'stage_not_recorded' ||
        (pass.state === 'skip' && !string(pass.skipped_reason)) ||
        (pass.runs === false && pass.state !== 'skip') ||
        (stage.state === 'skip' && pass.state !== 'skip')
      )
        return { ...result, reason: 'incomplete' };
    }
  }
  const response = value as unknown as PoMatchExplanationResponse;
  const stages = response.stages;
  const steps: PoReplayStep[] = [];
  for (const stage of stages) {
    if (stage.state !== 'skip') {
      for (const pass of stage.passes) {
        if (pass.runs) steps.push({ kind: 'pass', stage, pass });
      }
    }
    steps.push({ kind: 'stage', stage, pass: null });
  }
  steps.push({ kind: 'outcome', stage: null, pass: null });
  const lastEntered = [...stages]
    .reverse()
    .find((stage) => stage.state === 'pass' || stage.state === 'fail');
  const openPo = replayCount(lastEntered?.pending_po_lines_after);
  const openTable = replayCount(lastEntered?.pending_table_lines_after);
  const matched = replayCount(response.outcome?.matched_groups);
  const recordedHash = hash(value.trace.ruleset_hash);
  const currentHash = hash(response.ruleset?.hash);
  const evaluatedAt = string(value.trace.evaluated_at);
  const version = value.trace.ruleset_version;
  return {
    ...result,
    reason: '',
    stages,
    steps,
    openPo,
    openTable,
    matched,
    evaluatedAt:
      evaluatedAt && Number.isFinite(Date.parse(evaluatedAt))
        ? evaluatedAt
        : '',
    version:
      typeof version === 'number' || typeof version === 'string'
        ? String(version)
        : '',
    hash: recordedHash,
    basis:
      recordedHash && currentHash
        ? recordedHash === currentHash
          ? 'same'
          : 'different'
        : 'unknown',
    result:
      matched === 0
        ? 'none'
        : matched !== null &&
            matched > 0 &&
            openPo !== null &&
            openTable !== null
          ? openPo > 0 || openTable > 0
            ? 'partial'
            : response.outcome?.po_match_status === 'full_matched'
              ? 'full'
              : 'unknown'
          : 'unknown',
  };
}

/** Reveal only steps already visited; the current editor's rules never become trace facts. */
export function replayStagesAt(
  replay: PoReplay,
  index: number,
): PoMatchStage[] {
  const visited = replay.steps.slice(0, index + 1);
  return replay.stages.map((stage) => {
    const stageVisited = visited.some(
      (step) => step.kind === 'stage' && step.stage?.key === stage.key,
    );
    return {
      ...stage,
      rules: [],
      rule_names: [],
      state: stageVisited ? stage.state : null,
      skipped_reason_label: stageVisited ? stage.skipped_reason_label : null,
      passes: stage.passes.map((pass) => {
        const passVisited =
          stageVisited ||
          visited.some(
            (step) =>
              step.stage?.key === stage.key && step.pass?.key === pass.key,
          );
        return {
          ...pass,
          state: passVisited ? pass.state : null,
          matched: passVisited ? pass.matched : null,
          skipped_reason_label: passVisited ? pass.skipped_reason_label : null,
          failed_columns: [],
        };
      }),
    };
  });
}
